"""Derive SkyyPets/build_skyypets_0.4.18.py from SkyyPets 0.4.17 (SkyyPets/build_skyypets_0.4.17.py = the SET pin, itself GENERATED by
tools/pets_0_4_17_patch.py - never edit a generated script, edit this patch). Every anchor is asserted once; at the end every change is
undone on a copy and compared with 0.4.17 (tools/soundpass_gen.Patch). Line endings kept.
Run:  python tools/pets_0_4_18_patch.py   then   python SkyyPets/build_skyypets_0.4.18.py   (never --deploy)
      then  python SkyyPets/test_skyypets_0.4.18.py
Needs the kit's static_row(icon_bg=...) (tools/skyyui.py, 2026-10-24, additive).
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

NOTE = '''0.4.18 (2026-10-24) = PET RARITY COLOURS (docs/answered/pets.md 2026-10-24 PET RARITY COLOURS + PET TOOLTIP APPROVED; PROJECT-RULES 4
  "Rarity colours + tooltip layout everywhere"). Skyy: "can you color code the icon and the popup text to the pets rarity like we did for the
  items?" + "and make that the global default. if it has a rarity, it gets color coded." The colours = the item ones (RARITY_COLORS: the
  vanilla item qualities Common / Uncommon / Rare / Epic / Legendary + the Skyy_Pet_Mythic quality #CC66CC - what the pet eggs, our
  rarity tokens and every vanilla item already show; Style Guide 15).
  1. THE GRIDS (Pets grid, Hatchery "Fuse pets" grid): each pet cell = a hidden RARITY PORTRAIT item Skyy_PetIcon_<Kind>_<Rarity> (44 kinds x 6
     = 264 icon items under Server/Item/Items/SkyyPets/PetFrames/, the SAME picture as the kind's portrait, Quality = the rarity's quality,
     Variant (never in the creative library), no recipe / interaction, the base portrait's name key - no new lang line) with the item
     quality background ON (0.4.17: off) - so the engine draws the cell's frame AND the hover popup (frame + title) in the pet's rarity,
     exactly as it does for an item of that quality. The base Skyy_PetIcon_<Kind> ids stay (SkyyWardrobe, the hatch reel, PetsPage.iconOf).
     A kind an admin added without a portrait keeps its tool icon without a frame (its own item quality would be the wrong colour).
     The egg grid already wore the eggs' own qualities (unchanged).
  2. THE ROWS (Pet slot + Summon slot, the starter choice, Eggs craft rows, Hatchery slot rows): the icon sits on a square in its rarity
     colour (kit static_row icon_bg: a 44 px square, 2 px frame + tint at 40 %; an empty slot / unknown egg = a faint grey square). Eggs =
     their rarity; our dragon eggs = Legendary (their item quality); Aures' dragon eggs and unreadable lines = grey. Row names stay soft
     white (readability: Epic #8b339e text is only ~2.4:1 on the row panel), the slot tag keeps its rarity colour (0.4.0).
  3. THE HATCH RESULT card: the pet's picture = its rarity portrait with the quality frame (reel 1 still spins the plain portraits - the
     rarity is not known until reel 2 stops).
  The approved sectioned tooltip (type / name in the rarity colour / BUFFS NOW / ... / PROGRESS / ABILITIES) is unchanged - only colour added.
  SAVED DATA: none. FLOOR (rollback): to 0.4.17 alone (no data; the PetFrames items simply go away with the jar). The 0.4.17 / 0.4.15 /
  0.4.11 floors stand.
'''

P = G.Patch(os.path.join(ROOT, "SkyyPets", "build_skyypets_0.4.17.py"), os.path.join(ROOT, "SkyyPets", "build_skyypets_0.4.18.py"))
if "--out" in sys.argv:
    P.dst = os.path.abspath(sys.argv[sys.argv.index("--out") + 1])
assert P.has('VERSION = "0.4.17"') and P.has("public static double hatchCut(java.util.UUID u)") and not P.has("portraitR"), "not the generated SkyyPets 0.4.17 script"
REG0, SYS0, CLS0 = P.s.count("registerCommand("), P.s.count("registerSystem("), P.s.count("= cls(")

P.rep('''"""SkyyPets 0.4.17 - build script (javassist via jpype, tools/skyybuild.py). GENERATED by tools/pets_0_4_17_patch.py from SkyyPets 0.4.16
(build_skyypets_0.4.16.py, the SET pin, itself generated by tools/pets_0_4_16_patch.py) - edit the patch, never this file.
Owner: Skyy (they/them). Run:  python SkyyPets/build_skyypets_0.4.17.py   -> SkyyPets/SkyyPets-0.4.17.jar
(no --deploy on purpose: tools/deploy_set.py installs the set once the round is ready). Test: python SkyyPets/test_skyypets_0.4.17.py
''', '''"""SkyyPets 0.4.18 - build script (javassist via jpype, tools/skyybuild.py). GENERATED by tools/pets_0_4_18_patch.py from SkyyPets 0.4.17
(build_skyypets_0.4.17.py, the SET pin, itself generated by tools/pets_0_4_17_patch.py) - edit the patch, never this file.
Owner: Skyy (they/them). Run:  python SkyyPets/build_skyypets_0.4.18.py   -> SkyyPets/SkyyPets-0.4.18.jar
(no --deploy on purpose: tools/deploy_set.py installs the set once the round is ready). Test: python SkyyPets/test_skyypets_0.4.18.py

''' + NOTE + '''
SkyyPets 0.4.17 (generated by tools/pets_0_4_17_patch.py from 0.4.16) - everything below is still true unless 0.4.18 above says otherwise:
''')
P.rep('VERSION = "0.4.17"\n', 'VERSION = "0.4.18"\n')

# ======================================================================================================== the colours (one place)
P.rep('''RARITY_COLORS = [SUI.QUALITY["Common"], SUI.QUALITY["Uncommon"], SUI.QUALITY["Rare"], SUI.QUALITY["Epic"], SUI.QUALITY["Legendary"],
                 SUI.RARITY["Mythic"]]
''', '''RARITY_COLORS = [SUI.QUALITY["Common"], SUI.QUALITY["Uncommon"], SUI.QUALITY["Rare"], SUI.QUALITY["Epic"], SUI.QUALITY["Legendary"],
                 SUI.RARITY["Mythic"]]
# 0.4.18 (Skyy 2026-10-24 "color code the icon ... to the pets rarity like we did for the items"): the row icon square = the rarity colour at
# RBG_ALPHA (kit static_row icon_bg); no rarity / empty = the kit's disabled grey, fainter
RBG_ALPHA = "0.4"
RBG_NONE = SUI.COLOR["disabled"] + "(0.15)"
FRAME_DIR = "Server/Item/Items/SkyyPets/PetFrames"
''')

# ======================================================================================================== PetEggDefs: the rarity portrait ids
P.rep('''M(egd, "public static String portrait(String kind) { return kind == null ? null : @PKG@.PetLook.lookupCi(PORTRAITS, kind); }")
''', '''M(egd, "public static String portrait(String kind) { return kind == null ? null : @PKG@.PetLook.lookupCi(PORTRAITS, kind); }")
# 0.4.18: the kind's portrait in a rarity = the hidden icon item <portrait>_<Rarity> (Quality = that rarity: the engine draws the frame +
# the popup in its colour); null = no portrait (an admin-added kind) or no rarity
M(egd, r"""
public static String portraitR(String kind, int r) {
  String p = portrait(kind);
  if (p == null || r < 1 || r > @PKG@.PetKind.RARITIES.length) return null;
  return p + "_" + @PKG@.PetKind.rarityName(r);
}""")
M(egd, r"""
public static boolean isFramed(String icon) {
  if (icon == null || !icon.startsWith("Skyy_PetIcon_")) return false;
  int u = icon.lastIndexOf('_');
  return u > 12 && @PKG@.PetKind.rarityOf(icon.substring(u + 1)) > 0 && !icon.substring(u + 1).matches("[0-9]+");
}""")
# an egg's rarity for its colour: the 30 pet eggs by id, OUR dragon eggs = Legendary (their item quality), anything else (Aures' dragon
# eggs, an unknown id) = 0 (no rarity colour)
M(egd, r"""
public static int eggRar(String id) {
  int r = rarOfId(id);
  if (r > 0) return r;
  return id != null && id.startsWith(PREFIX) && isDragon(id) ? 5 : 0;
}""")
''')

# ======================================================================================================== PetsPage: the grid cells + the row square
P.rep('''M(PAGEC, r"""
public static String rcol(int r) {
  return r >= 1 && r <= RCOL.length ? RCOL[r - 1] : RCOL[0];
}""")
''', '''M(PAGEC, r"""
public static String rcol(int r) {
  return r >= 1 && r <= RCOL.length ? RCOL[r - 1] : RCOL[0];
}""")
# 0.4.18: the row icon square (kit static_row icon_bg) - the rarity colour at RBG_ALPHA; 0 / unknown = the faint grey
M(PAGEC, r"""
public static String rbg(int r) {
  return r >= 1 && r <= RCOL.length ? RCOL[r - 1] + "(@ALPHA@)" : "@NONE@";
}""".replace("@ALPHA@", RBG_ALPHA).replace("@NONE@", RBG_NONE))
''')
P.rep('''M(PAGEC, r"""
public static String xpText(@PKG@.PetRec r, String id) {''', '''# 0.4.18: a grid cell's item = the pet's RARITY portrait (frame + popup in its rarity); no portrait = iconOf (no frame)
M(PAGEC, r"""
public static String cellIcon(@PKG@.PetRec r, String id) {
  String p = @PKG@.PetEggDefs.portraitR(r.kindOf(id), r.rarityOf(id));
  return p != null ? p : iconOf(r, id);
}""")
M(PAGEC, r"""
public static String xpText(@PKG@.PetRec r, String id) {''')
P.rep('''public static @IGS@ cell(@PKG@.PetRec r, String id, int mode) {
  @IGS@ g = new @IGS@(new @IS@(iconOf(r, id), 1));
  g.setName(@PKG@.PetOps.petName(r, id) + " - Lv " + r.levelOf(id));
  g.setDescription(tip(r, id, mode));
  g.setSkipItemQualityBackground(true);''', '''public static @IGS@ cell(@PKG@.PetRec r, String id, int mode) {
  String ic = cellIcon(r, id);     // 0.4.18: the rarity portrait
  @IGS@ g = new @IGS@(new @IS@(ic, 1));
  g.setName(@PKG@.PetOps.petName(r, id) + " - Lv " + r.levelOf(id));
  g.setDescription(tip(r, id, mode));
  g.setSkipItemQualityBackground(!@PKG@.PetEggDefs.isFramed(ic));     // 0.4.18: the rarity frame + popup (0.4.17: always skipped)''')
P.rep('''      slots.add(this.emode == 2 ? @PKG@.PetHatchery.petCell(r, ids[i], iconOf(r, ids[i])) : @PKG@.PetHatchery.eggCell(u, r, inv, ids[i], this.emode));''',
      '''      slots.add(this.emode == 2 ? @PKG@.PetHatchery.petCell(r, ids[i], cellIcon(r, ids[i])) : @PKG@.PetHatchery.eggCell(u, r, inv, ids[i], this.emode));     // 0.4.18: the rarity portrait''')
P.rep('''    + "\\nMythic pets come only from eggs." + "\\n\\n<color is=" + q + (h.startsWith("+") ? "@TIPFOOT@" : "@TIPDIM@") + q + ">" + h.substring(1) + "</color>");
  g.setSkipItemQualityBackground(true);''', '''    + "\\nMythic pets come only from eggs." + "\\n\\n<color is=" + q + (h.startsWith("+") ? "@TIPFOOT@" : "@TIPDIM@") + q + ">" + h.substring(1) + "</color>");
  g.setSkipItemQualityBackground(!@PKG@.PetEggDefs.isFramed(icon));     // 0.4.18: the rarity frame + popup''')

# ---- the rows: icon_bg on the four static_row families (+ the runtime colour next to each row's other runtime values)
_IB = 'icon_bg=J_("ibg", SUI.QUALITY["Rare"] + "(" + RBG_ALPHA + ")"), '
for _old in ('''                       tag=J_("tg", "Full buffs"), tag_col=J_("tc", COL["gold"]), tag_w=220, action="Take out", action_w=112, action_on=True)''',
             '''                        tag=J_("tg", "Full buffs"), tag_col=J_("tc", COL["gold"]), tag_w=220, action="Take out", action_w=112, action_on=False)''',
             '''                       sub=J_("sb", "Up to +3.5 Mining Fortune at Lv 50"), tag=J_("tg", "Common"), tag_col=J_("tc", COL["gold"]), tag_w=200,
                       action="Choose", action_on=True)''',
             '''                        sub=J_("sb", "Up to +3.5 Mining Fortune at Lv 50"), tag=J_("tg", "Common"), tag_col=J_("tc", COL["gold"]), tag_w=200,
                        action="Choose", action_on=False)''',
             '''                       sub=J_("sb", "1 Egg (3) + 12 Enchanted Cobblestone (40)"), tag=J_("tg", "Ready"), tag_col=J_("tc", COL["gold"]), tag_w=150,
                       action="Craft", action_w=112, action_on=True)''',
             '''                        sub=J_("sb", "1 Egg (3) + 12 Enchanted Cobblestone (40)"), tag=J_("tg", "Ready"), tag_col=J_("tc", COL["gold"]), tag_w=150,
                        action="Craft", action_w=112, action_on=False)''',
             '''                                          sub=J_("sb", "Hatching - 4m 10s left"), tag=J_("tg", "4m 10s"), tag_col=J_("tc", COL["gold"]), tag_w=150,
                                          action=act, action_w=112, action_on=on)'''):
    _ind = _old[:len(_old) - len(_old.lstrip(" "))]
    P.rep(_old, _ind + _IB + _old.lstrip(" "))
assert not P.has("String ibg"), "0.4.18: ibg is a new name in every row loop"
P.rep('''    String tc = on ? rcol(r.rarityOf(sid)) : "@DISABLED@";
@SLOT@''', '''    String tc = on ? rcol(r.rarityOf(sid)) : "@DISABLED@";
    String ibg = rbg(on ? r.rarityOf(sid) : 0);     // 0.4.18: the icon square in the pet's rarity
@SLOT@''')
P.rep('''      String tc = rcol(1);
@CROW@''', '''      String tc = rcol(1);
      String ibg = rbg(on ? 1 : 0);     // 0.4.18: starters are Common
@CROW@''')
P.rep('''    String tc = can ? "@GOLD@" : "@DISABLED@";
@EROW@''', '''    String tc = can ? "@GOLD@" : "@DISABLED@";
    String ibg = rbg(@PKG@.PetEggDefs.eggRar(eid));     // 0.4.18: the egg's rarity
@EROW@''')
P.rep('''    String tc = stt == 2 ? "@GOLD@" : "@DISABLED@";
    if (stt == 2) {''', '''    String tc = stt == 2 ? "@GOLD@" : "@DISABLED@";
    String ibg = rbg(known ? @PKG@.PetEggDefs.eggRar(ln[0]) : 0);     // 0.4.18: the egg's rarity
    if (stt == 2) {''')

# ======================================================================================================== the hatch result card
P.rep('''    b.set("#SkyyHtR.Slots", one(portraitOf(this.kind), false));''',
      '''    String rpo = @PKG@.PetEggDefs.portraitR(this.kind, this.prar);     // 0.4.18: the rarity portrait with its quality frame
    b.set("#SkyyHtR.Slots", rpo != null ? one(rpo, true) : one(portraitOf(this.kind), false));''')

# ======================================================================================================== the 264 rarity portrait items
P.rep('''_pp = [EGG_FILES.get("Common/Icons/ItemsGenerated/%s.png" % PORTRAIT_ID[_k]) for _k in sorted(PORTRAIT_ID) if _k not in PORTRAIT_FALLBACK]
assert len(set(_pp)) == len(_pp), "0.4.0: two pets share a portrait"
''', '''_pp = [EGG_FILES.get("Common/Icons/ItemsGenerated/%s.png" % PORTRAIT_ID[_k]) for _k in sorted(PORTRAIT_ID) if _k not in PORTRAIT_FALLBACK]
assert len(set(_pp)) == len(_pp), "0.4.0: two pets share a portrait"
# 0.4.18 PET RARITY COLOURS: one hidden icon item per kind x rarity - the base portrait's JSON (same picture, same name key) + the rarity's
# Quality (vanilla Common .. Legendary, our Skyy_Pet_Mythic), under PetFrames/ (the 0.4.0 Icons/ count stays 50). No new picture, no lang line.
_fr = 0
for _k in sorted(PORTRAIT_ID):
    _base = json.loads(EGG_FILES["Server/Item/Items/SkyyPets/Icons/%s.json" % PORTRAIT_ID[_k]])
    assert "Quality" not in _base and _base["Variant"] is True and not ({"Recipe", "Interactions", "Categories"} & set(_base)), _k
    assert ("Common/" + _base["Icon"]) in EGG_FILES, ("0.4.18: the portrait picture is in the jar", _k)
    for _r in RARITIES:
        _iid = "%s_%s" % (PORTRAIT_ID[_k], _r)
        assert _iid not in ITEMS and _iid not in PORTRAIT_ID.values() and _iid not in TOKEN_ID.values(), _iid
        _p = "%s/%s.json" % (FRAME_DIR, _iid)
        assert _p not in EGG_FILES and _p not in _AZS040, _p
        EGG_FILES[_p] = json.dumps(dict(_base, Quality=EGG.QUALITY[_r]), indent=2)
        _fr += 1
assert _fr == len(PORTRAIT_ID) * 6 == 264, _fr
assert set(EGG.QUALITY.values()) == {"Common", "Uncommon", "Rare", "Epic", "Legendary", _MQ}, "0.4.18: the frames use the egg / item qualities"
assert all(("Server/Item/Qualities/%s.json" % _q) in _AZS040 for _q in EGG.QUALITY.values() if _q != _MQ) and ("Server/Item/Qualities/%s.json" % _MQ) in EGG_FILES
print("0.4.18 rarity portraits: %d icon items (%d kinds x 6 rarities) under %s" % (_fr, len(PORTRAIT_ID), FRAME_DIR))
''')

assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0 and P.s.count("= cls(") == CLS0, "0.4.18 adds no class, system or command"
assert P.s.count("String ibg = ") == 4 and P.s.count('icon_bg=J_("ibg"') == 7, "0.4.18: the four row loops + seven row looks"
_i = P.s.index
assert _i("public static String portraitR(") < _i("public static boolean isFramed(") < _i("public static int eggRar(") < _i('pinv = pool.makeInterface(PKG + ".PetInv")'), "0.4.18: PetEggDefs order"
assert _i("public static String rcol(int r)") < _i("public static String rbg(int r)") < _i("public static String iconOf(") < _i("public static String cellIcon(") \
    < _i("public static @IGS@ cell(") < _i("public void fillEggGrid("), "0.4.18: methods before callers"
assert "iconOf(r, ids[i])" not in P.s and P.s.count("cellIcon(r, ") == 2, "0.4.18: every grid cell takes the rarity portrait"
P.finish()
